#include "CitizenIdentityRuntime.hpp"
namespace elysium::citizens {bool CitizenIdentityRuntime::add(CitizenIdentity c,std::string&w){if(!c.id||!c.speciesId){w="invalid citizen";return false;}if(!rows_.emplace(c.id,std::move(c)).second){w="duplicate citizen";return false;}return true;}std::optional<LifeTransition>CitizenIdentityRuntime::transition(StableId id,LifeState to,std::uint64_t tick,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown citizen";return std::nullopt;}auto from=i->second.state;if(from==LifeState::Dead){w="dead citizen immutable";return std::nullopt;}i->second.state=to;i->second.lastStrategicUpdate=tick;LifeTransition t{id,from,to,tick,{}};if(to==LifeState::Dead){i->second.persistence=PersistencePolicy::HistoryPersistent;t.consequences={"history.death","relationships.loss","offices.vacate","logistics.remains"};}else if(to==LifeState::Departed)t.consequences={"history.departure","household.update"};else if(to==LifeState::Incapacitated)t.consequences={"medical.request","jobs.release"};return t;}bool CitizenIdentityRuntime::canCompact(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return false;auto&c=i->second;return c.persistence==PersistencePolicy::CohortCompactable&&!c.historySignificant&&c.relationships.empty()&&c.state==LifeState::Active;}}
